<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Leonida Legends - GTA VI Trophy Guide</title>
<meta name="description" content="An offline, sourced guide and progress tracker for all 55 GTA VI trophies.">
<link rel="stylesheet" href="style.css">
</head>
<body>
<div class="wrap">

  <header class="masthead">
    <div class="mast-copy">
      <div class="kicker"><span class="dot"></span> LEONIDA FIELD GUIDE · OFFLINE EDITION</div>
      <h1>Leonida Legends <span>— GTA VI Trophy Guide</span></h1>
      <p class="sub">All 55 official trophies, in plain language, with a source beside every guide. Tick what you earn; progress stays on this device.</p>
    </div>
    <div class="progress-card" aria-label="Overall progress">
      <div class="progress-top">
        <span class="progress-label">Platinum progress</span>
        <strong id="earnedCount">0 / 55</strong>
      </div>
      <div class="bar" role="progressbar" aria-valuemin="0" aria-valuemax="55" aria-valuenow="0" id="progressBar">
        <div class="bar-fill" id="progressFill"></div>
      </div>
      <div class="progress-foot">
        <span id="progressPct">0%</span>
        <span>54 trophies + platinum</span>
      </div>
    </div>
  </header>

  <section class="toolbar" aria-label="Tracker controls">
    <label class="search-wrap">
      <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"></circle><path d="M15.5 15.5 21 21"></path></svg>
      <input id="search" type="search" placeholder="Search name, description, guide…" autocomplete="off" spellcheck="false">
    </label>

    <div class="chips" id="kinds" role="group" aria-label="Filter by kind">
      <button class="chip is-active" type="button" data-kind="all">All</button>
      <button class="chip" type="button" data-kind="story">Story</button>
      <button class="chip" type="button" data-kind="missable">Missable</button>
      <button class="chip" type="button" data-kind="collectibles">Collectibles</button>
      <button class="chip" type="button" data-kind="activities">Activities</button>
      <button class="chip" type="button" data-kind="online">Online</button>
    </div>

    <label class="toggle" title="Hide the names and descriptions of unearned story trophies">
      <input id="spoilers" type="checkbox">
      <span class="switch" aria-hidden="true"></span>
      <span class="toggle-text">Hide spoilers</span>
