        <h2 id="checklistHeading">Trophy checklist</h2>
        <span class="muted" id="shownCount">55 shown</span>
      </div>
      <div id="checklist" class="checklist" role="list"></div>
    </section>

    <aside class="panel detail-panel" id="detail" aria-label="Trophy detail" aria-live="polite">
      <div class="empty-detail">
        <div class="empty-glyph">◆</div>
        <h3>Pick a trophy</h3>
        <p>Select any row to read its official description, the field guide, its source and the exact steps.</p>
      </div>
    </aside>
  </main>

  <section class="section" id="roadmapSection" aria-labelledby="roadmapHeading">
    <div class="section-head">
      <div>
        <div class="kicker">ROADMAP</div>
        <h2 id="roadmapHeading">Six stages to platinum</h2>
      </div>
      <p class="muted">Follow the order, clear the missable window in stage 3, and let the last stage mop up everything else.</p>
    </div>
    <div class="stage-grid" id="roadmap"></div>
  </section>

  <section class="section" id="missablesSection" aria-labelledby="missablesHeading">
    <div class="section-head">
      <div>
        <div class="kicker danger-kicker">WATCH THESE</div>
        <h2 id="missablesHeading">Missables and why they matter</h2>
      </div>
      <p class="muted">Every trophy whose official description hints at a fixed scene, a partner window or a one-shot moment.</p>
    </div>
    <div class="missable-grid" id="missables"></div>
  </section>

  <footer class="footer">
    <span>Leonida Legends · an independent, offline guide.</span>
    <span>Trophy names and descriptions are the official PlayStation list. Guides are original; cited sources are reference text only and are never fetched.</span>
  </footer>

</div>
<script type="module" src="app.js"></script>
</body>
</html>
