/* Leonida Legends — dusk / neon field guide. System fonts, no assets, no network. */
:root {
  --bg: #0a0913;
  --panel: rgba(24, 21, 45, 0.82);
  --panel-2: rgba(32, 28, 58, 0.72);
  --line: rgba(176, 123, 255, 0.18);
  --line-soft: rgba(194, 188, 235, 0.10);
  --text: #f0efff;
  --muted: #a5a1c5;
  --teal: #45e6c6;
  --purple: #b07bff;
  --amber: #ffc46b;
  --danger: #ff7d99;
  --radius: 14px;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  min-height: 100vh;
  color: var(--text);
  font: 14px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background:
    radial-gradient(900px 520px at 8% -8%, rgba(176, 123, 255, 0.20), transparent 70%),
    radial-gradient(760px 480px at 92% 4%, rgba(69, 230, 198, 0.13), transparent 70%),
    radial-gradient(700px 500px at 60% 100%, rgba(255, 196, 107, 0.08), transparent 70%),
    var(--bg);
  -webkit-font-smoothing: antialiased;
}
button, input { font: inherit; }
button { cursor: pointer; }
.wrap { max-width: 1240px; margin: 0 auto; padding: 20px 24px 44px; }

.kicker {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 10px; font-weight: 800; letter-spacing: 0.17em;
  color: var(--teal); text-transform: uppercase;
}
.kicker .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--teal); box-shadow: 0 0 10px var(--teal); }
