  transition: width 260ms ease;
}

/* ---------- toolbar ---------- */
.toolbar {
  display: flex; flex-wrap: wrap; align-items: center; gap: 10px;
  padding: 14px 0 16px;
}
.search-wrap {
  display: flex; align-items: center; gap: 8px; flex: 1 1 230px; min-width: 190px;
  background: rgba(255,255,255,0.05); border: 1px solid var(--line-soft);
  border-radius: 10px; padding: 7px 10px;
}
.search-wrap:focus-within { border-color: var(--teal); box-shadow: 0 0 0 3px rgba(69,230,198,0.10); }
.search-wrap svg { width: 15px; height: 15px; fill: none; stroke: var(--muted); stroke-width: 2; flex: none; }
.search-wrap input { width: 100%; border: 0; outline: 0; background: transparent; color: var(--text); font-size: 13px; }
.search-wrap input::placeholder { color: #77739b; }

.chips { display: flex; flex-wrap: wrap; gap: 5px; }
.chip {
  border: 1px solid var(--line-soft); background: rgba(255,255,255,0.04); color: var(--muted);
  border-radius: 99px; padding: 6px 11px; font-size: 11px; font-weight: 700; letter-spacing: 0.02em;
  transition: all 130ms ease;
}
.chip:hover { color: var(--text); border-color: var(--line); }
.chip.is-active {
  color: #0b0a16; border-color: transparent;
  background: linear-gradient(100deg, var(--teal), #9be9d6);
  box-shadow: 0 3px 14px rgba(69,230,198,0.24);
}

.toggle { display: inline-flex; align-items: center; gap: 8px; cursor: pointer; user-select: none; }
.toggle input { position: absolute; opacity: 0; width: 0; height: 0; }
.switch { width: 34px; height: 19px; border-radius: 99px; background: rgba(255,255,255,0.14); border: 1px solid var(--line-soft); position: relative; transition: all 150ms ease; flex: none; }
.switch::after { content: ""; position: absolute; top: 2px; left: 2px; width: 13px; height: 13px; border-radius: 50%; background: #cfcbe9; transition: all 150ms ease; }
.toggle input:checked + .switch { background: linear-gradient(90deg, var(--purple), var(--teal)); border-color: transparent; }
.toggle input:checked + .switch::after { transform: translateX(15px); background: #fff; }
.toggle-text { font-size: 11px; font-weight: 700; color: var(--muted); }
.toggle input:checked ~ .toggle-text { color: var(--teal); }

.actions { display: flex; gap: 6px; margin-left: auto; }
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  border: 1px solid var(--line); background: rgba(176,123,255,0.10); color: var(--text);
