.grade-silver { background: linear-gradient(100deg, #e7ecf5, #b7c2d3); color: #202b3b; }
.grade-bronze { background: linear-gradient(100deg, #e6a877, #b97143); color: #2c1508; }
.tag { border-radius: 5px; padding: 2px 6px; font-size: 9px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.05em; border: 1px solid var(--line); color: var(--muted); }
